package render

import (
	"image/color"
)

// The game uses its own 8x8 bitmap font.
//
// A hand-rolled bitmap font is used instead of a font renderer because:
//
//   - it guarantees the crisp, pixel-perfect look of the original game,
//   - it needs no external font file at runtime,
//   - it renders instantly (no shaping, no hinting, no atlas building).
//
// The glyph table is generated by tools/fontgen/main.py.

// CharWidth is the width of a character cell in pixels.
const CharWidth = 8

// CharHeight is the height of a character cell in pixels.
const CharHeight = 8

// CharAdvance is the horizontal advance of a character in pixels.
const CharAdvance = 8

// LineHeight is the vertical distance between two text lines.
const LineHeight = 10

// TextWidth returns the pixel width of a string in the bitmap font.
//
// A newline resets the advance, so the width of a multi-line string is the
// width of its longest line.
func TextWidth(s string) int {
	maxW := 0
	w := 0
	for _, r := range s {
		if r == '\n' {
			if w > maxW {
				maxW = w
			}
			w = 0
			continue
		}
		w += CharAdvance
	}
	if w > maxW {
		maxW = w
	}
	return maxW
}

// TextHeight returns the pixel height of a multi-line string.
func TextHeight(s string) int {
	lines := 1
	for _, r := range s {
		if r == '\n' {
			lines++
		}
	}
	return lines*LineHeight - (LineHeight - CharHeight)
}

// TextColor is the default colour of the text.
var TextColor = color.RGBA{0xe6, 0xe0, 0xc8, 0xff}
